package io.github.long0823.tclbondriver;
import android.app.*;import android.content.*;import android.net.wifi.WifiManager;import android.os.*;import java.util.concurrent.*;
public final class NetworkService extends Service {
 static final String PREFS="network-service";static volatile NetworkService instance;static volatile boolean active;static volatile String state="停止中";
 private PowerManager.WakeLock cpu;private WifiManager.WifiLock wifi;private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile boolean closed;private volatile IptvServer iptv;private boolean loading;
 static void enable(Context c,boolean enabled){c.getSharedPreferences(PREFS,0).edit().putBoolean("enabled",enabled).commit();Intent intent=new Intent(c,NetworkService.class);if(enabled)c.startForegroundService(intent);else c.stopService(intent);}
 @Override public void onCreate(){super.onCreate();instance=this;NotificationManager notifications=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);notifications.createNotificationChannel(new NotificationChannel("tcl-network","TVの通信維持",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);startForeground(43,new Notification.Builder(this,"tcl-network").setSmallIcon(io.github.long0823.tclbondriver.R.drawable.icon).setContentTitle("TCL TV 通信維持").setContentText("画面消灯中もWi-Fi・有線LANの配信処理を維持します").setContentIntent(open).setOngoing(true).build());cpu=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"TCLBonDriver:network");cpu.setReferenceCounted(false);cpu.acquire();WifiManager manager=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);if(manager!=null){wifi=manager.createWifiLock(WifiManager.WIFI_MODE_FULL_HIGH_PERF,"TCLBonDriver:wifi");wifi.setReferenceCounted(false);wifi.acquire();}active=true;state="通信維持中（画面は消灯できます）";}
 static synchronized String accessCode(Context c){android.content.SharedPreferences prefs=c.getSharedPreferences(PREFS,0);String code=prefs.getString("iptv_access_code","");if(!code.matches("[a-f0-9]{48}")){byte[] random=new byte[24];new java.security.SecureRandom().nextBytes(random);StringBuilder b=new StringBuilder();for(byte value:random)b.append(String.format(java.util.Locale.ROOT,"%02x",value&255));code=b.toString();prefs.edit().putString("iptv_access_code",code).commit();}return code;}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null&&"io.github.long0823.tclbondriver.ENABLE".equals(intent.getAction()))getSharedPreferences(PREFS,0).edit().putBoolean("enabled",true).commit();if(!getSharedPreferences(PREFS,0).getBoolean("enabled",false)){stopSelf();return START_NOT_STICKY;}if(!loading){loading=true;worker.execute(()->{try{byte[] profile=PhonePairing.export(this);IptvCatalog catalog=IptvCatalog.parse(profile);NativeGateway gateway=new NativeGateway(profile);if(closed)return;IptvServer opened=new IptvServer(catalog,gateway,new EpgStore(catalog,new java.io.File(getFilesDir(),"xmltv-epg.json")),accessCode(this),40560);synchronized(this){if(closed){opened.close();return;}iptv=opened;}state="通信維持・IPTV配信中（"+catalog.channels.size()+"局）";}catch(Exception e){state="通信維持中・IPTV準備失敗（root許可・局スキャンを確認）";android.util.Log.w("TclNetwork","IPTV startup failed: "+e.getClass().getSimpleName());loading=false;}});}return START_STICKY;}
 static String epgStatus(){NetworkService s=instance;return s!=null&&s.iptv!=null?s.iptv.epgStatus():"XMLTV準備中";}
 static String refreshEpg(){NetworkService s=instance;return s!=null&&s.iptv!=null?s.iptv.refreshEpg():"先に通信維持を有効にしてください";}
 @Override public IBinder onBind(Intent intent){return null;}
 @Override public void onDestroy(){closed=true;if(instance==this)instance=null;synchronized(this){if(iptv!=null)iptv.close();}worker.shutdownNow();if(wifi!=null&&wifi.isHeld())wifi.release();if(cpu!=null&&cpu.isHeld())cpu.release();active=false;state="停止中";stopForeground(true);super.onDestroy();}
}